package com.qfk.match.entity;
import com.qfk.member.entity.Member; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="match_registrations",uniqueConstraints=@UniqueConstraint(columnNames={"match_id","member_id"})) public class MatchRegistration {@Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @ManyToOne(optional=false) @JoinColumn(name="match_id") public FootballMatch match; @ManyToOne(optional=false) @JoinColumn(name="member_id") public Member member; @Enumerated(EnumType.STRING) public Status status; @Column(nullable=false) public Instant registeredAt; public Integer waitlistPosition; @Enumerated(EnumType.STRING) public PaymentStatus paymentStatus=PaymentStatus.PENDING; @Enumerated(EnumType.STRING) public AttendanceStatus attendanceStatus=AttendanceStatus.NOT_MARKED; public enum Status{CONFIRMED,WAITLIST,CANCELLED,REMOVED} public enum PaymentStatus{PENDING,PAID,WAIVED,REFUNDED} public enum AttendanceStatus{NOT_MARKED,PRESENT,ABSENT,EXCUSED}}
